class Html5Qrcode {
    static async getCameras() {
        if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
            throw new Error('Camera access not supported.');
        }
        const tempStream = await navigator.mediaDevices.getUserMedia({ video: true });
        tempStream.getTracks().forEach(track => track.stop());
        const devices = await navigator.mediaDevices.enumerateDevices();
        return devices
            .filter(device => device.kind === 'videoinput')
            .map((device, index) => ({ id: device.deviceId, label: device.label || 'Camera ' + (index + 1) }));
    }
    constructor(elementId) {
        this.elementId = elementId;
        this.video = document.createElement('video');
        this.container = document.getElementById(elementId);
        this.container.innerHTML = '';
        this.container.appendChild(this.video);
        this.scanActive = false;
    }
    async start(cameraIdOrConfig, config, qrCodeSuccessCallback, qrCodeErrorCallback) {
        if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
            throw new Error('Camera access not supported.');
        }
        const constraints = { video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } } };
        if (typeof cameraIdOrConfig === 'string') {
            constraints.video.deviceId = { exact: cameraIdOrConfig };
        }
        const stream = await navigator.mediaDevices.getUserMedia(constraints);
        this.video.srcObject = stream;
        this.video.setAttribute('playsinline', true);
        await this.video.play();
        this.scanActive = true;
        this.canvas = document.createElement('canvas');
        this.context = this.canvas.getContext('2d', { willReadFrequently: true });
        if ('BarcodeDetector' in window) {
            try {
                this._detector = new BarcodeDetector({ formats: ['qr_code'] });
            } catch (e) {
                this._detector = null;
            }
        }
        const scanFrame = async () => {
            if (!this.scanActive) return;
            if (this.video.readyState === this.video.HAVE_ENOUGH_DATA && this.video.videoWidth) {
                this.canvas.width = this.video.videoWidth;
                this.canvas.height = this.video.videoHeight;
                this.context.drawImage(this.video, 0, 0, this.canvas.width, this.canvas.height);
                let decodedValue = null;
                if (this._detector) {
                    try {
                        const barcodes = await this._detector.detect(this.canvas);
                        if (barcodes.length) {
                            decodedValue = barcodes[0].rawValue;
                        }
                    } catch (e) {
                        this._detector = null;
                    }
                }
                if (!decodedValue && typeof jsQR === 'function') {
                    const imageData = this.context.getImageData(0, 0, this.canvas.width, this.canvas.height);
                    const code = jsQR(imageData.data, imageData.width, imageData.height, { inversionAttempts: 'attemptBoth' });
                    if (code && code.data) {
                        decodedValue = code.data;
                    }
                }
                if (decodedValue) {
                    qrCodeSuccessCallback(decodedValue, {});
                } else if (typeof qrCodeErrorCallback === 'function') {
                    qrCodeErrorCallback('No QR code found in frame.');
                }
            }
            if (this.scanActive) {
                requestAnimationFrame(scanFrame);
            }
        };
        scanFrame();
    }
    stop() {
        this.scanActive = false;
        const stream = this.video.srcObject;
        if (stream) {
            stream.getTracks().forEach(track => track.stop());
        }
        this.video.srcObject = null;
    }
    clear() {
        if (this.container) {
            this.container.innerHTML = '';
        }
    }
}
